/**
 * is-odd -> a function the project owns (JavaScript, "raise").
 *
 * Why this pair: the "raise" path of the product. There is no package to move to: the answer is
 * six lines the project can own. The séance is what makes owning them safe, because it asks the
 * original about every kind of value (strings, arrays, bigints, symbols, huge numbers).
 */

import type { KnownDifference, SeanceBundle, SeanceFile } from '../../types.js';
import { callsNote, jsProjectCalls } from '../examples.js';
import { renderReadme } from '../readme.js';
import { makeBundle, type Mutant, type Recipe, type RecipeContext } from '../recipe.js';
import { depOfContext, oldVersionsFor } from '../versions.js';

const DIR = 'seance/is-odd';
const VENDOR = 'src/vendor/is-odd.mjs';

export const IS_ODD_KNOWN: KnownDifference[] = [
  {
    input: 'isOdd("abc")',
    old: 'throws TypeError (expected a number)',
    naive: 'false (NaN % 2 is NaN, which is not 1)',
    handled:
      'Reproduced: the replacement converts with Math.abs and checks the result, like is-odd.',
  },
  {
    input: 'isOdd(3.5)',
    old: 'throws Error ("expected an integer")',
    naive: 'false',
    handled: 'Reproduced.',
  },
  {
    input: 'isOdd(2 ** 53)',
    old: 'throws Error ("value exceeds maximum safe integer")',
    naive: 'false',
    handled: 'Reproduced.',
  },
];

function replacementSource(): string {
  return [
    '// is-odd, owned by the project. Generated by Necromancer (recipe "is-odd").',
    '// Dependency-free (is-odd also needed is-number). Kept identical to is-odd 3.0.1 for every',
    '// input the séance compares, including the unusual ones: strings, arrays, null, bigint.',
    'export function isOdd(value) {',
    '  const n = Math.abs(value); // converts like is-odd: "3" and [3] are 3, null is 0',
    "  if (!Number.isFinite(n)) throw new TypeError('expected a number');",
    "  if (!Number.isInteger(n)) throw new Error('expected an integer');",
    "  if (!Number.isSafeInteger(n)) throw new Error('value exceeds maximum safe integer');",
    '  return n % 2 === 1;',
    '}',
    '',
  ].join('\n');
}

function testSource(projectCalls: string[]): string {
  return [
    '// Séance: is-odd -> src/vendor/is-odd.mjs. Generated by Necromancer (recipe "is-odd").',
    '// Run: npx vitest run seance/is-odd',
    '//',
    '// Compared: the boolean returned or, when the call throws, the error class (never the message).',
    "import { describe, it, expect } from 'vitest';",
    "import fc from 'fast-check';",
    "import isOddOld from 'is-odd';",
    "import { isOdd } from '../../src/vendor/is-odd.mjs';",
    '',
    'const outcome = (fn, args) => {',
    '  try {',
    '    return { ok: true, value: fn(...args) };',
    '  } catch (e) {',
    '    return { ok: false, error: e && e.constructor ? e.constructor.name : typeof e };',
    '  }',
    '};',
    '',
    '// What a reader would try first.',
    'const naive = (n) => n % 2 === 1 || n % 2 === -1;',
    '',
    'const strangeNumbers = fc.constantFrom(0, -0, 1, -1, 2 ** 53, 2 ** 53 - 1, -(2 ** 53), 1e21, 1e-7, 0.5, -0.5, Infinity, -Infinity, NaN);',
    "const strange = fc.constantFrom(null, undefined, true, false, '', ' ', ' 5', '0x10', '-3', '3.5', 'abc', '9007199254740993', [], [3], [3, 4], {}, { valueOf: () => 3 }, Symbol('x'), 3n, () => 1);",
    'const value = fc.oneof(fc.integer(), fc.maxSafeInteger(), fc.double({ noNaN: false }), strangeNumbers, strange, fc.string(), fc.bigInt(), fc.integer().map(String), fc.array(fc.integer(), { maxLength: 2 }));',
    '',
    ...projectCalls,
    '',
    "describe('seance: is-odd -> owned function', () => {",
    "  it('the owned function answers like is-odd for any value', () => {",
    '    fc.assert(',
    '      fc.property(value, (v) => {',
    '        expect(outcome(isOdd, [v])).toEqual(outcome(isOddOld, [v]));',
    '      }),',
    '      { numRuns: 3000 },',
    '    );',
    '  });',
    '',
    "  it('it answers like is-odd for every integer in a window around zero and around the safe limit', () => {",
    '    for (let n = -300; n <= 300; n++) expect(outcome(isOdd, [n])).toEqual(outcome(isOddOld, [n]));',
    '    // A step counter, not n++: above 2^53 adding 1 to a double changes nothing.',
    '    for (let k = -300; k <= 300; k++) {',
    '      const n = Number.MAX_SAFE_INTEGER + k;',
    '      expect(outcome(isOdd, [n]), String(n)).toEqual(outcome(isOddOld, [n]));',
    '      expect(outcome(isOdd, [-n]), String(-n)).toEqual(outcome(isOddOld, [-n]));',
    '    }',
    '  });',
    '',
    "  it('it answers like is-odd on the calls this project makes', () => {",
    '    for (const args of projectCalls) expect(outcome(isOdd, args), JSON.stringify(args)).toEqual(outcome(isOddOld, args));',
    '  });',
    '',
    "  it('the naive rewrite n % 2 === 1 is not the same function', () => {",
    '    // Values on which the obvious rewrite answers differently from is-odd.',
    '    const differing = [3.5, 2 ** 53, "abc", undefined, {}];',
    '    for (const v of differing) {',
    '      expect(outcome(naive, [v]), String(v)).not.toEqual(outcome(isOddOld, [v]));',
    '      expect(outcome(isOdd, [v]), String(v)).toEqual(outcome(isOddOld, [v]));',
    '    }',
    '  });',
    '});',
    '',
  ].join('\n');
}

function build(ctx: RecipeContext): SeanceBundle {
  const pick = (m: string): boolean => m === 'default' || m === 'isOdd';
  const files: SeanceFile[] = [
    {
      path: `${DIR}/seance.test.mjs`,
      content: testSource(jsProjectCalls(ctx.usage, pick)),
      role: 'test',
    },
    { path: VENDOR, content: replacementSource(), role: 'replacement' },
  ];
  const compares = [
    'The boolean returned, or the error class when the call throws (never the message).',
    'Inputs: integers, safe-integer edges, doubles, NaN and infinities, numeric strings, arrays, null, undefined, booleans, objects with valueOf, bigint, symbols, functions.',
    callsNote(ctx.usage, pick),
  ];
  const install = ['npm install --save-dev vitest fast-check'];
  const oldVersions = oldVersionsFor('is-odd', depOfContext(ctx));
  compares.push(`Versions: ${oldVersions.note}`);
  const run = 'npx vitest run seance/is-odd';
  files.push({
    path: `${DIR}/README.md`,
    role: 'readme',
    content: renderReadme({
      title: 'is-odd, raised into your own code',
      recipe: 'is-odd',
      files: [
        {
          path: `${DIR}/seance.test.mjs`,
          what: 'the differential property test against the original package',
        },
        { path: VENDOR, what: 'the function your project owns from now on (no dependency)' },
      ],
      install,
      run,
      compares,
      known: IS_ODD_KNOWN,
      versions: oldVersions.note,
      notes: [
        'After the switch, remove is-odd (and is-number) from package.json and keep this test, with the original recorded or still installed as a dev dependency.',
      ],
    }),
  });
  return makeBundle({
    language: 'javascript',
    recipe: 'is-odd',
    title: 'is-odd, raised into your own code',
    files,
    install,
    run,
    compares,
    knownDifferences: IS_ODD_KNOWN,
    members: ['default'],
    oldVersions,
  });
}

function mutants(): Mutant[] {
  const path = VENDOR;
  return [
    {
      id: 'no-conversion',
      description: 'the obvious rewrite: n % 2 === 1, no Math.abs, no validation',
      files: [
        {
          path,
          role: 'replacement',
          content: 'export function isOdd(n) { return n % 2 === 1 || n % 2 === -1; }\n',
        },
      ],
    },
    {
      id: 'missing-safe-integer-check',
      description: 'forgets to reject integers above the safe limit',
      files: [
        {
          path,
          role: 'replacement',
          content: replacementSource().replace(
            "  if (!Number.isSafeInteger(n)) throw new Error('value exceeds maximum safe integer');\n",
            '',
          ),
        },
      ],
    },
  ];
}

export const isOddRecipe: Recipe = {
  id: 'is-odd',
  language: 'javascript',
  ecosystem: 'npm',
  old: 'is-odd',
  successors: ['is-odd'],
  kind: 'raise',
  why: 'The raise path: no package to move to, so the project owns six lines and the séance proves they are the same.',
  build,
  mutants,
};
